parameters.command:
sqlite3 -json "/data/arabic_dict.db" "
SELECT headword, definitions_text FROM entries WHERE dictionary_id=151 AND headword LIKE 'حص%';
"

sqlite3 -json "/data/arabic_dict.db" "
SELECT headword, definitions_text FROM entries WHERE dictionary_id=151 AND (headword LIKE 'حصي%' OR headword LIKE 'حصو%');
"

sqlite3 -json "/data/arabic_dict.db" "
SELECT headword, headword_norm, definitions_text FROM entries WHERE dictionary_id=151 AND headword_norm LIKE 'حص%';
"

sqlite3 -json "/data/arabic_dict.db" "
SELECT headword, definitions_text FROM entries WHERE dictionary_id=151 AND headword_norm = 'علم';
"
